fn extract_rear_chars(l: &Vec<Vec<char>>) -> Vec<char> {
    // Pre-allocate the result with the same length as the outer vector
    let mut result = Vec::with_capacity(l.len());
    // For each inner vector, take its last element (each is guaranteed non-empty)
    for inner in l {
        // inner[inner.len() - 1] is safe because inner is non-empty
        result.push(inner[inner.len() - 1]);
    }
    result
}

// Example usage and test
fn main() {
    let input: Vec<Vec<char>> = vec![
        vec!['a', 'b', 'c'],
        vec!['x'],
        vec!['1', '2', '3', '4'],
    ];
    let output = extract_rear_chars(&input);
    assert_eq!(output, vec!['c', 'x', '4']);

    let empty_outer: Vec<Vec<char>> = Vec::new();
    let output_empty = extract_rear_chars(&empty_outer);
    assert!(output_empty.is_empty());
}